css:
:root { --radius: 2px; }
[data-slot="button"],
[data-slot="input"],
[data-slot="select-trigger"],
[data-thread-item],
[data-user-message-bubble],
[data-thread-details-card],
[data-slot="composer-host"],
.chat-markdown-codeblock {
  border-radius: 2px !important;
  box-shadow: none !important;
}
[data-slot="dialog-popup"],
[data-slot="popover-popup"],
[data-slot="menu-popup"],
[data-slot="tooltip-popup"] {
  border-radius: 2px !important;
  box-shadow: 2px 2px 0 rgba(41,42,38,.12) !important;
}
[data-chat-header] {
  border-bottom: 1px solid var(--border) !important;
  box-shadow: none !important;
}
[data-slot="sidebar-inner"] { box-shadow: none !important; }
[data-thread-item] { border-radius: 0 !important; }
[data-slot="composer-host"] {
  border: 1px solid var(--border) !important;
  background: var(--input) !important;
}
[data-user-message-bubble] {
  border: 1px solid var(--border) !important;
}
.chat-markdown {
  font-family: Charter, "Iowan Old Style", "Palatino Linotype", "Noto Serif KR", "AppleMyungjo", "Batang", Georgia, serif !important;
  font-size: 16px;
  line-height: 1.85 !important;
  letter-spacing: .005em;
}
.chat-markdown :is(h1,h2,h3,h4) {
  font-family: inherit !important;
  letter-spacing: -.02em;
  line-height: 1.4 !important;
}
.chat-markdown :is(pre,code,kbd) {
  font-family: var(--font-mono), monospace !important;
  letter-spacing: normal;
}
.chat-markdown blockquote {
  border-left-width: 1px !important;
}
.chat-markdown a {
  text-decoration: underline;
  text-underline-offset: 3px;
  text-decoration-thickness: 1px;
}
.chat-markdown-codeblock {
  border: 1px solid var(--border) !important;
  line-height: 1.6 !important;
}
svg.lucide { stroke-width: 1.5; }
[data-slot="scroll-area-thumb"] { border-radius: 0 !important; }

/* Typesetting and restrained structural details. */
.chat-markdown :is(h1,h2) {
  border-bottom: 1px solid var(--border);
  padding-bottom: .45em;
  margin-top: 1.65em;
  margin-bottom: .85em;
}
.chat-markdown h3 { margin-top: 1.5em; margin-bottom: .65em; }
.chat-markdown p { text-wrap: pretty; }
.chat-markdown :is(ul,ol) { padding-inline-start: 1.5em; }
.chat-markdown li::marker { color: var(--muted-foreground); }
.chat-markdown blockquote {
  background: transparent !important;
  border-color: var(--border) !important;
  border-radius: 0 !important;
  color: var(--muted-foreground);
  padding-inline-start: 1.2em;
  font-style: normal;
}
.chat-markdown hr {
  height: 0;
  border: 0;
  border-top: 1px solid var(--border);
  margin-block: 2em;
}
.chat-markdown table { font-variant-numeric: tabular-nums; }
.chat-markdown :is(th,td) {
  border-color: var(--border) !important;
  padding: .65em .85em;
}
.chat-markdown th {
  background: var(--muted) !important;
  font-weight: 600;
}
.chat-markdown :is(img,video) { border-radius: 2px !important; }
.chat-markdown ::selection,
.composer-tiptap ::selection {
  background: #d8dacb;
  color: #20221b;
}
[data-user-message-bubble] {
  border-inline-start-color: #85877b !important;
}
[data-slot="composer-host"]:focus-within {
  border-color: #777b6b !important;
}
[data-slot="input"]:focus-visible,
[data-slot="select-trigger"]:focus-visible,
[data-slot="button"]:focus-visible {
  outline: 2px solid #50534a !important;
  outline-offset: 2px;
}
[data-thread-details-card] {
  border: 1px solid var(--border) !important;
}
[data-slot="project-monogram"] { border-radius: 2px !important; }
[data-slot="tooltip-popup"] {
  font-size: 12px;
  letter-spacing: .015em;
}

/* Paper texture: background layers only; text and controls stay crisp. */
[data-workspace-area="conversation"],
[data-settings-page-scroll],
[data-slot="dialog-popup"],
[data-slot="popover-popup"],
[data-slot="menu-popup"] {
  background-image:
    url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%3Cfilter%20id%3D%22grain%22%20x%3D%220%22%20y%3D%220%22%20width%3D%22100%25%22%20height%3D%22100%25%22%3E%3CfeTurbulence%20type%3D%22fractalNoise%22%20baseFrequency%3D%22.62%22%20numOctaves%3D%223%22%20stitchTiles%3D%22stitch%22%2F%3E%3CfeColorMatrix%20type%3D%22saturate%22%20values%3D%220%22%2F%3E%3CfeComponentTransfer%3E%3CfeFuncR%20type%3D%22linear%22%20slope%3D%221.8%22%20intercept%3D%22-.4%22%2F%3E%3CfeFuncG%20type%3D%22linear%22%20slope%3D%221.8%22%20intercept%3D%22-.4%22%2F%3E%3CfeFuncB%20type%3D%22linear%22%20slope%3D%221.8%22%20intercept%3D%22-.4%22%2F%3E%3CfeFuncA%20type%3D%22linear%22%20slope%3D%22.16%22%2F%3E%3C%2FfeComponentTransfer%3E%3C%2Ffilter%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20filter%3D%22url(%23grain)%22%2F%3E%3C%2Fsvg%3E"),
    radial-gradient(ellipse at 48% 24%,
      rgba(255,255,250,.55) 0%,
      rgba(255,255,250,.10) 45%,
      rgba(76,69,48,.09) 100%) !important;
  background-size: 160px 160px, 100% 100% !important;
  background-repeat: repeat, no-repeat !important;

  background-color: #f3f1e9 !important;
}
[data-slot="sidebar-inner"],
nav[data-workspace-area="settings-nav"],
nav:has([data-settings-section]) {
  background-color: #eeeee7 !important;
  background-image:
    url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22192%22%20height%3D%22192%22%20viewBox%3D%220%200%20192%20192%22%3E%3Cfilter%20id%3D%22grain%22%20x%3D%220%22%20y%3D%220%22%20width%3D%22100%25%22%20height%3D%22100%25%22%3E%3CfeTurbulence%20type%3D%22fractalNoise%22%20baseFrequency%3D%22.72%22%20numOctaves%3D%223%22%20stitchTiles%3D%22stitch%22%2F%3E%3CfeColorMatrix%20type%3D%22saturate%22%20values%3D%220%22%2F%3E%3CfeComponentTransfer%3E%3CfeFuncR%20type%3D%22linear%22%20slope%3D%222.5%22%20intercept%3D%22-.75%22%2F%3E%3CfeFuncG%20type%3D%22linear%22%20slope%3D%222.5%22%20intercept%3D%22-.75%22%2F%3E%3CfeFuncB%20type%3D%22linear%22%20slope%3D%222.5%22%20intercept%3D%22-.75%22%2F%3E%3CfeFuncA%20type%3D%22linear%22%20slope%3D%22.29%22%2F%3E%3C%2FfeComponentTransfer%3E%3C%2Ffilter%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20filter%3D%22url(%23grain)%22%2F%3E%3C%2Fsvg%3E"),
    radial-gradient(ellipse 130% 32% at 5% 32%, rgba(168,202,190,.55), transparent 85%),
    radial-gradient(ellipse 140% 38% at 100% 66%, rgba(169,205,193,.65), transparent 85%),
    radial-gradient(ellipse 150% 30% at 65% 110%, rgba(218,201,136,.65), transparent 85%),
    linear-gradient(165deg, #efeae9 0%, #eff0e9 48%, #e8eee4 78%, #eae4c9 100%) !important;
  background-size: 192px 192px, 100% 100%, 100% 100%, 100% 100%, 100% 100% !important;
  background-repeat: repeat, no-repeat, no-repeat, no-repeat, no-repeat !important;
}

/* Shared paper controls, selection and semantic colors. */
:root {
  --success: #427357;
  --success-foreground: #365943;
  --info: #557784;
  --info-foreground: #365565;
}
[data-slot="settings-group"],
[data-slot="card"] {
  border-radius: 2px !important;
  border: 1px solid #c6c5ba !important;
  background-color: rgba(248,246,239,.78) !important;
  box-shadow: none !important;
}
[data-slot="settings-row"] {
  border-radius: 0 !important;
  border-color: #d3d1c6 !important;
}
[data-settings-section] { border-radius: 2px !important; }
[data-settings-section][aria-current="page"],
[data-sidebar-row][aria-current="page"],
[data-thread-item] [aria-current="page"] {
  background-color: rgba(248,246,239,.18) !important;
  color: #292e28 !important;
  box-shadow: inset 0 0 0 1px #657b68 !important;
}
:is([data-settings-section], [data-sidebar-row])[aria-current="page"] :is(span,svg) {
  color: #292e28 !important;
}
[data-thread-item] button[aria-label="Dismiss Woke notification"] {
  color: #365943 !important;
}
[data-sidebar-row][aria-current="page"] button[aria-label="Dismiss Woke notification"] {
  color: #365943 !important;
}
[data-settings-section]:not([aria-current="page"]):hover {
  background-color: #bfd0c2 !important;
}
[data-slot="input-control"],
[data-slot="textarea"],
[data-slot="select-trigger"] {
  border: 1px solid #85877b !important;
  border-radius: 2px !important;
  background-color: #f8f6ef !important;
  color: #292a26 !important;
  box-shadow: none !important;
}
[data-slot="input"][aria-invalid="true"],
[data-slot="textarea"][aria-invalid="true"],
[data-slot="select-trigger"][aria-invalid="true"] {
  border-color: #914636 !important;
}
:is([data-slot="switch"],[role="switch"]) {
  border: 0 !important;
  border-radius: 3px !important;
  box-shadow: none !important;
}
:is([data-slot="switch"],[role="switch"]):is([aria-checked="true"],[data-checked]) {
  background-color: #505b4a !important;
}
:is([data-slot="switch"],[role="switch"]):is([aria-checked="false"],[data-unchecked]) {
  background-color: #dedfd3 !important;
}
[data-slot="switch-thumb"] {
  border-radius: 2px !important;
  background-color: #faf8f0 !important;
  box-shadow: none !important;
}
[data-slot="button"][aria-pressed="true"] {
  box-shadow: inset 0 -2px 0 #505b4a !important;
}
[data-slot="input"]:focus-visible,
[data-slot="textarea"]:focus-visible,
[data-slot="select-trigger"]:focus-visible,
[data-slot="button"]:focus-visible,
:is([data-slot="switch"],[role="switch"]):focus-visible,
[data-settings-section]:focus-visible {
  outline: 2px solid #50534a !important;
  outline-offset: -2px !important;
}
[data-workspace-area="settings-nav"] + div > header,
[data-chat-header] {
  background-color: rgba(238,236,228,.88) !important;
  border-bottom: 1px solid #c6c5ba !important;
  box-shadow: none !important;
}
[data-slot="popover-popup"],
[data-slot="menu-popup"],
[data-slot="tooltip-popup"],
[data-slot="select-popup"] {
  background-color: #f8f6ef !important;
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%20viewBox%3D%220%200%20160%20160%22%3E%3Cfilter%20id%3D%22grain%22%20x%3D%220%22%20y%3D%220%22%20width%3D%22100%25%22%20height%3D%22100%25%22%3E%3CfeTurbulence%20type%3D%22fractalNoise%22%20baseFrequency%3D%22.62%22%20numOctaves%3D%223%22%20stitchTiles%3D%22stitch%22%2F%3E%3CfeColorMatrix%20type%3D%22saturate%22%20values%3D%220%22%2F%3E%3CfeComponentTransfer%3E%3CfeFuncR%20type%3D%22linear%22%20slope%3D%221.8%22%20intercept%3D%22-.4%22%2F%3E%3CfeFuncG%20type%3D%22linear%22%20slope%3D%221.8%22%20intercept%3D%22-.4%22%2F%3E%3CfeFuncB%20type%3D%22linear%22%20slope%3D%221.8%22%20intercept%3D%22-.4%22%2F%3E%3CfeFuncA%20type%3D%22linear%22%20slope%3D%22.07%22%2F%3E%3C%2FfeComponentTransfer%3E%3C%2Ffilter%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20filter%3D%22url(%23grain)%22%2F%3E%3C%2Fsvg%3E") !important;
  background-size: 160px 160px !important;
  background-repeat: repeat !important;
  color: #292a26 !important;
  border: 1px solid #85877b !important;
  border-radius: 2px !important;
  box-shadow: 2px 2px 0 rgba(41,42,38,.12) !important;
}
[data-slot="tooltip-popup"] { line-height: 1.5; }

/* Hover stays visible; the selected row keeps its thin frame. */
@media (hover: hover) {
  [data-sidebar-row]:hover,
  [data-thread-item]:hover [data-sidebar-row],
  [data-settings-section]:hover,
  [data-slot="sidebar-menu-button"]:hover {
    background-color: #bfd0c2 !important;
    color: #292e28 !important;
  }
  :is([data-settings-section], [data-sidebar-row])[aria-current="page"]:hover,
  [data-thread-item]:hover [data-sidebar-row][aria-current="page"] {
    background-color: #cbd8cb !important;
    box-shadow: inset 0 0 0 1px #657b68 !important;
  }
}

/* Replace only the sidebar home wordmark; retain the existing link. */
a[aria-label="T3 Code home"] {
  color: #292e28 !important;
  border-radius: 2px !important;
  margin-left: calc(var(--workspace-controls-left) + var(--workspace-titlebar-control-size) + 9px) !important;
  padding-inline: 0;
  text-decoration: none !important;
}
a[aria-label="T3 Code home"] > span { display: none !important; }
a[aria-label="T3 Code home"]::before {
  content: "＋ New";
  font-family: var(--font-sans), sans-serif;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: .015em;
  white-space: nowrap;
}
@media (hover: hover) {
  a[aria-label="T3 Code home"]:hover {
    background-color: #bfd0c2 !important;
  }
}
a[aria-label="T3 Code home"]:focus-visible {
  outline: 2px solid #50534a !important;
  outline-offset: -2px !important;
}

/* Input owns the text; its wrapper owns the surface and border. */
[data-slot="input-control"] > [data-slot="input"] {
  border: 0 !important;
  background-color: transparent !important;
  box-shadow: none !important;
}
[data-slot="input-control"]:has(> [data-slot="input"][aria-invalid="true"]) {
  border-color: #914636 !important;
}
[data-slot="input-control"]:has(> input:is([type="search"],[placeholder^="Search" i],[aria-label^="Search" i])) {
  border: 0 !important;
  background-color: transparent !important;
  box-shadow: none !important;
  border-radius: 2px !important;
}
[data-slot="input-control"]:has(> input:is([type="search"],[placeholder^="Search" i],[aria-label^="Search" i]))::before {
  box-shadow: none !important;
}
[data-slot="input-control"] > input:is([type="search"],[placeholder^="Search" i],[aria-label^="Search" i]):focus-visible {
  outline: none !important;
}
[data-slot="input-control"]:has(> input:is([type="search"],[placeholder^="Search" i],[aria-label^="Search" i]):focus-visible) {
  box-shadow: inset 0 -2px 0 #50534a !important;
}
/* Usage period, metric and breakdown selectors. */
[data-slot="toggle-group"]:is([aria-label="Usage period"],[aria-label="Usage metric"],[aria-label="Usage breakdown"]) {
  background-color: rgba(226,228,216,.55) !important;
  border-radius: 2px !important;
}
[data-slot="toggle-group"]:is([aria-label="Usage period"],[aria-label="Usage metric"],[aria-label="Usage breakdown"]) [data-slot="toggle"] {
  border-radius: 2px !important;
  color: #5d6358 !important;
  box-shadow: none !important;
}
[data-slot="toggle-group"]:is([aria-label="Usage period"],[aria-label="Usage metric"],[aria-label="Usage breakdown"]) [data-slot="toggle"]:is([data-pressed],[aria-pressed="true"]) {
  background-color: #c3d4c7 !important;
  color: #292e28 !important;
  font-weight: 600 !important;
  box-shadow: inset 0 -2px 0 #526b58 !important;
}
@media (hover: hover) {
  [data-slot="toggle-group"]:is([aria-label="Usage period"],[aria-label="Usage metric"],[aria-label="Usage breakdown"]) [data-slot="toggle"]:not([data-pressed]):not([aria-pressed="true"]):hover {
    background-color: #d7e1d4 !important;
    color: #292e28 !important;
  }
}

/* Square primary composer action, including its disabled state. */
[data-chat-composer-form] button[type="submit"],
[data-chat-composer-form] button[aria-label="Resume thread"],
[data-slot="composer-host"] button[type="submit"],
[data-slot="composer-host"] button[aria-label="Resume thread"] {
  border-radius: 2px !important;
  box-shadow: none !important;
}

/* Keep Stop and Stopping aligned with the square send action. */
button:is([aria-label="Stop generation"],[aria-label="Stopping"]) {
  border-radius: 2px !important;
  box-shadow: none !important;
}

/* Warm paper messages without cast shadows. */
[data-user-message-bubble] {
  background-color: #f8f2e5 !important;
  background-image: url("data:image/svg+xml,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22160%22%20height%3D%22160%22%3E%3Cfilter%20id%3D%22grain%22%3E%3CfeTurbulence%20type%3D%22fractalNoise%22%20baseFrequency%3D%22.72%22%20numOctaves%3D%223%22%20stitchTiles%3D%22stitch%22%2F%3E%3CfeColorMatrix%20type%3D%22saturate%22%20values%3D%220%22%2F%3E%3CfeComponentTransfer%3E%3CfeFuncA%20type%3D%22linear%22%20slope%3D%22.10%22%2F%3E%3C%2FfeComponentTransfer%3E%3C%2Ffilter%3E%3Crect%20width%3D%22100%25%22%20height%3D%22100%25%22%20filter%3D%22url(%23grain)%22%2F%3E%3C%2Fsvg%3E") !important;
  background-size: 160px 160px !important;
  background-repeat: repeat !important;
  border: 1px solid #c5c0ae !important;
  border-inline-start-color: #c5c0ae !important;
  border-radius: 2px !important;
  box-shadow: none !important;
  color: #30322b !important;
  padding: 15px 21px !important;
}


/* Cut only the painted surfaces; content and popup overflow remain intact. */
[data-slot="composer-shell"]::before {
  content: none !important;
}
[data-slot="composer-host"] {
  position: relative;
  isolation: isolate;
  background: transparent !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 1px;
}
[data-slot="composer-host"]:focus-within {
  border: 0 !important;
}
[data-slot="composer-host"]::before,
[data-slot="composer-host"]::after {
  content: "" !important;
  display: block !important;
  position: absolute !important;
  width: auto !important;
  height: auto !important;
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  pointer-events: none !important;
}
[data-slot="composer-host"]::before {
  content: none !important;
}
[data-slot="composer-host"]::after,
[data-slot="composer-host"]:has([data-composer-banner-surface=attached]) [data-chat-composer-main-surface]::before {
  content: "" !important;
  position: absolute !important;
  inset: 0 !important;
  background-color: #ffffff !important;
  background-image: linear-gradient(225deg, transparent 49%, #e9e8e0 50%) !important;
  background-position: right top !important;
  background-size: 13px 13px !important;
  background-repeat: no-repeat !important;
  clip-path: polygon(0 0, calc(100% - 13px) 0, 100% 13px, 100% 100%, 0 100%);
  z-index: -1 !important;
}
/* An attached question drawer tucks under the input, so the paper moves there. */
[data-slot="composer-host"]:has([data-composer-banner-surface=attached])::after {
  content: none !important;
}
[data-composer-banner-surface]::before {
  border-radius: 2px !important;
}
/* Pending questions read as a sticky note on an e-ink page. */
[data-composer-banner-surface]:has([data-pending-user-input-dismiss])::before {
  background: #f3ecc4 !important;
  border: 1px solid #2a2a28 !important;
  mask: none !important;
}
[data-chat-composer-main-surface] {
  isolation: isolate;
  background-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
[data-chat-composer-main-surface]::after {
  border: 0 !important;
  box-shadow: none !important;
}
[data-user-message-bubble],
[data-user-message-bubble] .chat-markdown {
  font-size: 15px !important;
  line-height: 1.5 !important;
  letter-spacing: 0 !important;
}
[data-user-message-bubble] .chat-markdown p {
  line-height: inherit !important;
  margin-block: .2rem !important;
}
[data-user-message-bubble] .chat-markdown > :first-child {
  margin-top: 0 !important;
}
[data-user-message-bubble] .chat-markdown > :last-child {
  margin-bottom: 0 !important;
}

/* One square ink shadow follows the composer and any attached card. */
[data-slot="composer-host"] {
  filter: drop-shadow(3px 3px 0 #2a2a28) !important;
}

/* Keep navigation labels legible over grain and translucent hover surfaces. */
[data-settings-section],
nav[data-workspace-area="settings-nav"] h3 {
  color: #48523f !important;
}

/* Readable explanatory copy even when native-only controls are unavailable. */
[data-settings-page-scroll] :is(p,h3) {
  opacity: 1 !important;
}

/* Define off switches without changing track or thumb dimensions. */
:is([data-slot="switch"],[role="switch"]):is([aria-checked="false"],[data-unchecked]) {
  box-shadow: inset 0 0 0 1px #777b6b !important;
}
:is([data-slot="switch"],[role="switch"]):is([aria-checked="false"],[data-unchecked]) [data-slot="switch-thumb"] {
  box-shadow: inset 0 0 0 1px #777b6b !important;
}

/* Inactive navigation rows remain readable; disabled controls keep their state. */
[data-sidebar-row]:not([aria-disabled="true"]) {
  opacity: 1 !important;
}
